component.script:
"""JSON Handler: one operation on a list of records inside request_data.

One operation per node, by design: chain several nodes for a multi-step
pipeline, so each step reads on the canvas. The list is found by Array Path,
the result is added to the inbound data, and a misconfigured node raises
ValueError instead of quietly passing the data on unchanged.
"""

import perceivo

_OPERATIONS = ("extract", "filter", "transform", "aggregate", "sort", "select_fields", "normalize")
_FILTER_OPERATORS = ("equals", "not_equals", "contains", "gt", "lt", "gte", "lte")
_TRANSFORM_OPS = ("add", "multiply", "uppercase", "lowercase", "trim", "prefix", "suffix")
_AGGREGATE_FUNCTIONS = ("sum", "avg", "min", "max", "count")
_SORT_DIRECTIONS = ("ascending", "descending")
_TRUE, _FALSE = ("true", "1", "yes", "y", "on"), ("false", "0", "no", "n", "off")
_ABSENT = object()


def _param(name: str, default: str = "") -> str:
    """A text node parameter. An explicit 0 stays "0"; only None or "" fall back."""
    value = perceivo.params.get(name, default)
    if value is None or str(value).strip() == "":
        return default
    return str(value).strip()


def _choice(name: str, label: str, default: str, choices: tuple) -> str:
    value = _param(name, default).lower()
    if value not in choices:
        raise ValueError(f"{label} is {value!r}. Choose one of: {', '.join(choices)}.")
    return value


def _required(name: str, label: str, operation: str) -> str:
    value = _param(name)
    if not value:
        raise ValueError(f"{label} is required for the {operation} operation.")
    return value


def _number_param(name: str, label: str, default: float) -> float:
    raw = _param(name, str(default))
    try:
        return float(raw)
    except ValueError:
        raise ValueError(f"{label} is {raw!r}; it must be a number.") from None


def _resolve_path(data, dotted_path: str):
    """Walk a dot-notation path through nested dicts, or _ABSENT."""
    current = data
    for part in dotted_path.split("."):
        if not isinstance(current, dict) or part not in current:
            return _ABSENT
        current = current[part]
    return current


def _as_number(value):
    """The value as an int or float, or None when it is not numeric. Booleans are not numbers."""
    if isinstance(value, bool) or value is None:
        return None
    if isinstance(value, (int, float)):
        return value
    text = str(value).strip()
    try:
        return int(text)
    except ValueError:
        pass
    try:
        return float(text)
    except ValueError:
        return None


def _compare(left, operator: str, right: str) -> bool:
    """Evaluate one filter predicate against the configured value (always text).

    gt/lt/gte/lte compare numbers only, so a record whose field is not numeric
    never matches them. equals compares numbers as numbers ("2" equals 2.0),
    booleans against true/false/yes/no, a missing or null field as empty text,
    and anything else as text. contains matches a substring of text, or an
    element of a list.
    """
    if operator == "contains":
        if isinstance(left, list):
            return any(str(item) == right for item in left)
        return right in ("" if left is None else str(left))
    left_number, right_number = _as_number(left), _as_number(right)
    if operator in ("gt", "lt", "gte", "lte"):
        if left_number is None or right_number is None:
            return False
        return {
            "gt": left_number > right_number,
            "lt": left_number < right_number,
            "gte": left_number >= right_number,
            "lte": left_number <= right_number,
        }[operator]
    if isinstance(left, bool) and right.lower() in _TRUE + _FALSE:
        equal = left == (right.lower() in _TRUE)
    elif left_number is not None and right_number is not None:
        equal = left_number == right_number
    else:
        equal = ("" if left is None else str(left)) == right
    return equal if operator == "equals" else not equal


def _filter(items, field, operator, value):
    """Keep the records whose field satisfies the predicate."""
    return [i for i in items if isinstance(i, dict) and _compare(i.get(field), operator, value)]


def _transform(items, field, operation, operand):
    """Copies of the records with field transformed.

    add and multiply leave a value that is not a number as it is; the text
    operations treat a missing field as empty text.
    """
    if operation in ("add", "multiply"):
        delta = _as_number(operand)
        if delta is None:
            raise ValueError(f"Transform Operand is {operand!r}; {operation} needs a number.")
    result, skipped = [], 0
    for item in items:
        if not isinstance(item, dict):
            result.append(item)
            continue
        updated = dict(item)
        current = item.get(field)
        if operation in ("add", "multiply"):
            base = _as_number(current)
            if base is None:
                skipped += 1
            else:
                updated[field] = base + delta if operation == "add" else base * delta
        else:
            text = "" if current is None else str(current)
            updated[field] = {
                "uppercase": text.upper,
                "lowercase": text.lower,
                "trim": text.strip,
                "prefix": lambda: f"{operand}{text}",
                "suffix": lambda: f"{text}{operand}",
            }[operation]()
        result.append(updated)
    if skipped:
        perceivo.log.warning(
            f"JSON Handler: {skipped} record(s) left unchanged; {field} is not a number.",
            field=field,
            skipped=skipped,
        )
    return result


def _aggregate(items, field, function):
    """Reduce the records to one number.

    count counts the records. sum is 0 when no record has a numeric field;
    avg, min and max are null then, because there is nothing to measure.
    """
    if function == "count":
        return len(items)
    values = [
        n for n in (_as_number(i.get(field)) for i in items if isinstance(i, dict)) if n is not None
    ]
    if function == "sum":
        return sum(values)
    if not values:
        return None
    if function == "avg":
        return sum(values) / len(values)
    return min(values) if function == "min" else max(values)


def _sort(items, field, direction):
    """Order the records by field: numbers before text, missing values always last."""
    present, missing = [], []
    for item in items:
        value = item.get(field) if isinstance(item, dict) else None
        (missing if value is None else present).append(item)

    def key(item):
        value = item[field]
        number = _as_number(value)
        # (0, number) sorts every number before (1, text), so mixed types never raise.
        return (0, number, "") if number is not None else (1, 0, str(value))

    return sorted(present, key=key, reverse=direction == "descending") + missing


def _select_fields(items, wanted):
    """Only the named fields of each record."""
    return [{f: i[f] for f in wanted if f in i} if isinstance(i, dict) else i for i in items]


def _normalize(items, field, low, high):
    """Rescale a numeric field across the records into [low, high].

    When every value is the same they are all placed at low. A record whose
    field is not numeric is left as it is.
    """
    values = [
        n for n in (_as_number(i.get(field)) for i in items if isinstance(i, dict)) if n is not None
    ]
    if not values:
        return [dict(i) if isinstance(i, dict) else i for i in items]
    smallest, span = min(values), max(values) - min(values)
    result = []
    for item in items:
        updated = dict(item) if isinstance(item, dict) else item
        current = _as_number(item.get(field)) if isinstance(item, dict) else None
        if current is not None:
            ratio = 0.0 if span == 0 else (current - smallest) / span
            updated[field] = low + ratio * (high - low)
        result.append(updated)
    return result


def _run(operation: str, items: list):
    """Read the operation's own parameters, check them, and apply it to items."""
    if operation == "filter":
        field = _required("filter_field", "Filter Field", operation)
        operator = _choice("filter_operator", "Filter Operator", "equals", _FILTER_OPERATORS)
        return _filter(items, field, operator, _param("filter_value"))
    if operation == "transform":
        field = _required("transform_field", "Transform Field", operation)
        op = _choice("transform_op", "Transform Operation", "uppercase", _TRANSFORM_OPS)
        # Not stripped: a prefix may end, or a suffix start, with a space.
        operand = perceivo.params.get("transform_value", "")
        return _transform(items, field, op, "" if operand is None else str(operand))
    if operation == "aggregate":
        function = _choice("aggregate_function", "Aggregate Function", "sum", _AGGREGATE_FUNCTIONS)
        field = (
            ""
            if function == "count"
            else _required("aggregate_field", "Aggregate Field", operation)
        )
        return _aggregate(items, field, function)
    if operation == "sort":
        field = _required("sort_field", "Sort Field", operation)
        direction = _choice("sort_direction", "Sort Direction", "ascending", _SORT_DIRECTIONS)
        return _sort(items, field, direction)
    if operation == "select_fields":
        csv = _required("select_fields", "Fields To Keep", operation)
        return _select_fields(items, [f.strip() for f in csv.split(",") if f.strip()])
    field = _required("normalize_field", "Normalize Field", operation)
    low = _number_param("normalize_min", "Range Minimum", 0)
    high = _number_param("normalize_max", "Range Maximum", 1)
    return _normalize(items, field, low, high)


@perceivo.adapter
async def json_handler(
    input: perceivo.primitives.AdapterInput,
) -> perceivo.primitives.AdapterOutput:
    """Apply one configured operation to the list at Array Path.

    extract returns whatever sits at the path; every other operation needs a
    list there. The inbound request_data is spread into the result before the
    produced fields are named, so upstream context survives; nothing is
    removed, so there is no _except list. The artifact is forwarded straight
    into the Output and never dereferenced, so it is welcome but never required.

    A misconfigured node - an unknown operation, a missing field name, an Array
    Path that finds nothing or no list - raises ValueError.
    """
    request_data = input.request_data or {}
    if not isinstance(request_data, dict):
        request_data = {"data": request_data}

    operation = _choice("operation", "Operation", "filter", _OPERATIONS)
    array_path = _param("array_path")
    if not array_path:
        raise ValueError(
            "Array Path is required: the dot-notation path to the list in the incoming "
            f"data, e.g. results.items. Fields received: {sorted(request_data)}."
        )
    located = _resolve_path(request_data, array_path)
    if located is _ABSENT:
        raise ValueError(
            f"Array Path {array_path!r} is not in the incoming data. "
            f"Fields received: {sorted(request_data)}."
        )

    if operation == "extract":
        result = located
    elif isinstance(located, list):
        result = _run(operation, located)
    else:
        raise ValueError(
            f"Array Path {array_path!r} holds {type(located).__name__}, not a list; "
            f"{operation} needs a list."
        )

    item_count = len(result) if isinstance(result, list) else 0
    perceivo.log.info(
        f"JSON Handler: {operation} at {array_path} -> "
        f"{f'{item_count} item(s)' if isinstance(result, list) else 'one value'}",
        operation=operation,
        item_count=item_count,
    )

    return perceivo.primitives.AdapterOutput(
        artifact=input.artifact,
        response_data={
            **request_data,
            "result": result,
            "operation": operation,
            "item_count": item_count,
        },
    )
